import sys
from xml.dom import minidom

path = "unpacked/word/document.xml"
doc = minidom.parse(path)

ns = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"

def ln(elem):
    return elem.getElementsByTagNameNS(ns, "t") or elem.getElementsByTagNameNS(ns, "delText")

paras = doc.getElementsByTagNameNS(ns, "p")
for i, p in enumerate(paras):
    pPr = p.getElementsByTagNameNS(ns, "pPr")
    style = ""
    if pPr:
        st = pPr[0].getElementsByTagNameNS(ns, "pStyle")
        if st:
            style = st[0].getAttributeNS(ns, "val")
    texts = []
    for t in ln(p):
        texts.append(t.firstChild.nodeValue if t.firstChild else "")
    txt = "".join(texts)
    if style or txt.strip():
        print(f"[{i}] style={style!r} text={txt[:80]!r}")

import sys
from xml.dom import minidom

path = sys.argv[1] if len(sys.argv) > 1 else "unpacked/word/document.xml"
dom = minidom.parse(path)
W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"

def get_text(elem):
    parts = []
    for t in elem.getElementsByTagNameNS(W, "t"):
        if t.firstChild:
            parts.append(t.data)
    return "".join(parts)

body = dom.getElementsByTagNameNS(W, "body")[0]
for i, p in enumerate(body.getElementsByTagNameNS(W, "p")):
    pPr = p.getElementsByTagNameNS(W, "pPr")
    style = ""
    if pPr:
        pStyle = pPr[0].getElementsByTagNameNS(W, "pStyle")
        if pStyle and pStyle[0].getAttributeNS(W, "val"):
            style = pStyle[0].getAttributeNS(W, "val")
    txt = get_text(p).strip()
    if style or txt:
        print(f"P{i:03d} [{style}] {txt!r}")

"""Underline all report headlines in the unpacked quarterly_report.docx.

Headlines in this document are all-caps heading lines (e.g., "EXECUTIVE
SUMMARY", "FINANCIAL HIGHLIGHTS", "REVENUE BREAKDOWN BY SEGMENT", etc.);
they are structurally single-run paragraphs.  We detect them by content
(uppercase-only text containing letters) so that body paragraphs, bullets,
and the table header/data rows stay untouched, then add
<w:u w:val="single"/> to each headline run's run properties.
"""
import os
import sys

UNPACKED = "unpacked"

SKILL = os.path.join(os.getcwd(), ".codex", "skills", "docx")
if os.path.isdir(os.path.join(SKILL, "scripts")):
    sys.path.insert(0, SKILL)

try:
    from scripts.document import Document
    DOC_LIB = True
except Exception:
    import xml.dom.minidom as minidom
    DOC_LIB = False


def text_of(para):
    return "".join(
        (t.firstChild.data if t.firstChild else "")
        for t in para.getElementsByTagName("w:t")
    )


def is_headline(txt):
    return bool(txt.strip()) and txt.isupper() and any(ch.isalpha() for ch in txt)


def add_underline(dom, para):
    for r in [c for c in para.childNodes
              if c.nodeType == c.ELEMENT_NODE and c.tagName == "w:r"]:
        rprs = [c for c in r.childNodes
                if c.nodeType == c.ELEMENT_NODE and c.tagName == "w:rPr"]
        if rprs:
            rpr = rprs[0]
        else:
            rpr = dom.createElement("w:rPr")
            r.insertBefore(rpr, r.firstChild)
        if not any(c.nodeType == c.ELEMENT_NODE and c.tagName == "w:u"
                   for c in rpr.childNodes):
            u = dom.createElement("w:u")
            u.setAttribute("w:val", "single")
            rpr.appendChild(u)


def process(dom):
    count = 0
    for p in dom.getElementsByTagName("w:p"):
        if is_headline(text_of(p)):
            add_underline(dom, p)
            count += 1
    return count


if DOC_LIB:
    doc = Document(UNPACKED)
    count = process(doc["word/document.xml"].dom)
    doc.save()
else:
    path = os.path.join(UNPACKED, "word", "document.xml")
    dom = minidom.parse(path)
    count = process(dom)
    with open(path, "wb") as fh:
        fh.write(dom.toxml(encoding="ascii"))

print("underlined %d headline(s)" % count)

"""Underline all report headlines in the unpacked quarterly_report.docx.

Headlines in this document are all-caps heading lines (e.g., "EXECUTIVE
SUMMARY", "FINANCIAL HIGHLIGHTS", "REVENUE BREAKDOWN BY SEGMENT", etc.);
they are structurally single-run paragraphs.  We detect them by content
(uppercase-only text containing letters) so that body paragraphs, bullets,
and the table header/data rows stay untouched, then add
<w:u w:val="single"/> to each headline run's run properties.
"""
import os
import sys

UNPACKED = "unpacked"
PATH = os.path.join(UNPACKED, "word", "document.xml")

import xml.dom.minidom as minidom  # noqa: E402


def text_of(para):
    return "".join(
        (t.firstChild.data if t.firstChild else "")
        for t in para.getElementsByTagName("w:t")
    )


def is_headline(txt):
    return bool(txt.strip()) and txt.isupper() and any(ch.isalpha() for ch in txt)


def process(dom):
    count = 0
    for p in dom.getElementsByTagName("w:p"):
        if not is_headline(text_of(p)):
            continue
        for r in [c for c in p.childNodes
                  if c.nodeType == c.ELEMENT_NODE and c.tagName == "w:r"]:
            rprs = [c for c in r.childNodes
                    if c.nodeType == c.ELEMENT_NODE and c.tagName == "w:rPr"]
            if rprs:
                rpr = rprs[0]
            else:
                rpr = dom.createElement("w:rPr")
                r.insertBefore(rpr, r.firstChild)
            if not any(c.nodeType == c.ELEMENT_NODE and c.tagName == "w:u"
                       for c in rpr.childNodes):
                u = dom.createElement("w:u")
                u.setAttribute("w:val", "single")
                rpr.appendChild(u)
        count += 1
    return count


dom = minidom.parse(PATH)
count = process(dom)
with open(PATH, "wb") as fh:
    fh.write(dom.toxml(encoding="ascii"))

print("underlined %d headline(s)" % count)

import io

try:
    from defusedxml import minidom as xmldom
except Exception:
    from xml.dom import minidom as xmldom

W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"
XML_PATH = "q4work/word/document.xml"

U_SEQ = ['rStyle', 'rFonts', 'b', 'bCs', 'i', 'iCs', 'caps', 'smallCaps', 'strike',
         'dstrike', 'outline', 'shadow', 'emboss', 'imprint', 'noProof', 'snapToGrid',
         'vanish', 'webHidden', 'color', 'spacing', 'w', 'kern', 'position', 'sz',
         'szCs', 'highlight', 'u', 'effect', 'bdr', 'shd', 'fitText', 'vertAlign',
         'rtl', 'cs', 'em', 'lang', 'eastAsianLayout', 'specVanish', 'oMath']


def local(name):
    return name.split(':')[-1].split('}')[-1]


def is_headline(text):
    s = (text or '').strip()
    if len(s) < 4:
        return False
    if not any(c.isalpha() for c in s):
        return False
    if s != s.upper():
        return False
    return all(c.isalnum() or c in " &(),.:'/%-" for c in s)


def para_text(p):
    parts = []
    for r in p.getElementsByTagName('w:r'):
        for t in r.getElementsByTagName('w:t'):
            if t.firstChild and t.firstChild.nodeValue:
                parts.append(t.firstChild.nodeValue)
    return ''.join(parts)


doc = xmldom.parse(XML_PATH)
body = doc.getElementsByTagName('w:body')[0]
u_rank = U_SEQ.index('u')
changed = 0

for p in body.getElementsByTagName('w:p'):
    if not is_headline(para_text(p)):
        continue
    for r in p.getElementsByTagName('w:r'):
        rprs = r.getElementsByTagName('w:rPr')
        if rprs:
            rpr = rprs[0]
        else:
            rpr = doc.createElementNS(W, 'w:rPr')
            r.insertBefore(rpr, r.firstChild)
        if rpr.getElementsByTagName('w:u'):
            continue
        u = doc.createElementNS(W, 'w:u')
        u.setAttributeNS(W, 'w:val', 'single')
        anchor = None
        for c in rpr.childNodes:
            if c.nodeType == c.ELEMENT_NODE:
                n = local(c.tagName)
                if n in U_SEQ and U_SEQ.index(n) > u_rank:
                    anchor = c
                    break
        if anchor is not None:
            rpr.insertBefore(u, anchor)
        else:
            rpr.appendChild(u)
        changed += 1

buf = io.StringIO()
doc.documentElement.writexml(buf, indent='  ', addindent='  ', newl='\n')
out = '<?xml version="1.0" encoding="ascii"?>\n' + buf.getvalue()
with open(XML_PATH, 'w', encoding='ascii', errors='xmlcharrefreplace', newline='') as f:
    f.write(out)
print('underlined runs:', changed)

